"""Writes reconciliation.md and README.md of <MVP_LOAD_DIR>/main (default data/mvp-load; environment, then the repo .env,
stores.py) from the JSON made by build_main.py."""
import os, sys, json, collections
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from stores import mvp_load_dir
from decimal import Decimal as D, ROUND_HALF_UP
ROOT = os.path.abspath(os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', '..', '..', '..'))
OUT = mvp_load_dir('main')
rows = json.load(open(os.path.join(OUT, 'cash_rows.json')))
nicks = json.load(open(os.path.join(OUT, 'nicknames.json')))
pairs = json.load(open(os.path.join(OUT, 'carve_pairs.json')))
sch = json.load(open(os.path.join(OUT, 'sch3b_check.json')))
q2 = lambda x: x.quantize(D('0.01'), ROUND_HALF_UP)
f = lambda x: '{:,.2f}'.format(q2(x))

# parts view: (row, load, raw amount)
def parts(r):
    if 'parts' in r:
        tot = D(r['amountRaw'])
        res = []
        for p in r['parts']:
            res.append((p['load'], D(p['amount'])))
        # keep raw remainder exact on the last part
        s = sum(a for _, a in res)
        l, a = res[-1]; res[-1] = (l, a + (tot - s))
        return res
    return [(r['load'], D(r['amountRaw']))]

agg = collections.defaultdict(lambda: [0, D(0), D(0)])
for r in rows:
    for l, a in parts(r):
        k = (r['type'], r['category'], l)
        agg[k][0] += 1; agg[k][1] += a; agg[k][2] += q2(a)
exp = {k: v for k, v in agg.items() if k[0] == 'Expense'}
exp_total = sum(v[1] for v in exp.values()); exp_cents = sum(v[2] for v in exp.values())
exp_rows = [r for r in rows if r['type'] == 'Expense']
L = []
w = L.append
w('# Stage 4.5 reconciliation of `0to8 Main.xlsx` INCOME/EXPENSE\n')
w('Generated by `packages/backend/scripts/mvp/build_main.py` + `report_main.py` (read-only on the sources). Nicknames are stage names; no legal names, emails or bank data.\n')
w('Rows with a non-empty Type: **%d** (Expense %d, Income %d). Row numbers are sheet rows.\n' % (len(rows), len(exp_rows), len(rows) - len(exp_rows)))
w('## 1. Sums per (type, category, load class)\n')
w('`rows` counts parts (the MC Denny row 12904 and the DJ Raulipues row 6821 are split into two parts each). `sum` is the exact cell value (sub-cent cells kept); `sum per-row-cents` rounds every part to cents (what a loader in integer cents would store).\n')
w('| side | category | load | rows | sum | sum per-row-cents |\n|---|---|---|---:|---:|---:|')
for k in sorted(agg):
    v = agg[k]; w('| %s | %s | %s | %d | %s | %s |' % (k[0], k[1] or '(blank)', k[2], v[0], f(v[1]), f(v[2])))
w('')
w('## 2. Proof: Expense classes sum to 8,045,246.75\n')
w('| load class | parts | sum (exact cells) |\n|---|---:|---:|')
byclass = collections.defaultdict(lambda: [0, D(0)])
for k, v in exp.items(): byclass[k[2]][0] += v[0]; byclass[k[2]][1] += v[1]
for l in sorted(byclass): w('| %s | %d | %s |' % (l, byclass[l][0], f(byclass[l][1])))
w('| **total** | %d | **%s** |' % (sum(v[0] for v in byclass.values()), f(exp_total)))
w('')
w('- Every Expense row (%d) carries exactly one class (or explicit parts); no row is missing. The exact-cell total is %s = 8,045,246.75 (Main\'s "Для выплат" total; `recon_money.md`).' % (len(exp_rows), '{:,.6f}'.format(exp_total)))
dif = exp_cents - q2(exp_total)
w('- Rounding every row to cents gives %s, i.e. %s more than the exact total (%d Expense cells carry more than 2 decimals; the ledger sheet itself stores them unrounded). A loader in integer cents therefore drifts by that amount; stage 5 compares at the cent level and should expect it.' % (f(exp_cents), f(dif), sum(1 for r in exp_rows if D(r['amountRaw']) != q2(D(r['amountRaw'])))))
cash_to_load = sum(v[1] for k, v in exp.items() if k[2] in ('payout', 'advance'))
nl = sum(v[1] for k, v in exp.items() if k[2] == 'not_loaded')
w('- Expense minus the rows named as not loaded (Advertising %s; zero-amount rows %s) = %s.' % (f(sum(v[1] for k, v in exp.items() if k[2] == 'not_loaded' and k[1] == 'Advertising')), f(sum(v[1] for k, v in exp.items() if k[2] == 'not_loaded' and k[1] != 'Advertising')), f(exp_total - nl)))
w('- Of that: loaded cash (`payout` + `advance`) %s; `deduction` %s; `carve_pair` %s (ledger form of carves, not cash to the nickname); `document_only` %s; `review` %s (decision needed before loading).' % (
  f(cash_to_load), f(byclass['deduction'][1]), f(byclass['carve_pair'][1]), f(byclass['document_only'][1]), f(byclass['review'][1])))
w('')
# ---- nicknames
w('## 3. Nicknames')
st = collections.Counter(n['status'] for n in nicks.values())
w('\nDistinct nicknames in the sheet: %d (matched %d, ambiguous %d, unmatched %d).\n' % (len(nicks), st['matched'], st['ambiguous'], st['unmatched']))
paid = collections.defaultdict(lambda: [0, D(0)])
for r in exp_rows:
    for l, a in parts(r):
        if l in ('payout', 'advance', 'deduction'):
            paid[r['nickname']][0] += 1; paid[r['nickname']][1] += a
bad = [(n, v) for n, v in paid.items() if nicks[n]['status'] != 'matched']
w('### Nicknames with payouts / advances / deductions whose status is not `matched`: %d (sum %s)\n' % (len(bad), f(sum(v[1] for _, v in bad))))
w('| nickname | status | rows | sum |\n|---|---|---:|---:|')
for n, v in sorted(bad, key=lambda x: -x[1][1]): w('| %s | %s | %d | %s |' % (n, nicks[n]['status'], v[0], f(v[1])))
unm_all = [n for n, e in nicks.items() if e['status'] != 'matched']
unm_nopay = [n for n in unm_all if n not in paid]
w('\nNon-matched nicknames with no loaded cash row: %d (income-only, zero rows, or only document/carve/review rows).\n' % len(unm_nopay))
rev_nick = sorted({r['nickname'] for r in exp_rows if r['load'] == 'review' and nicks[r['nickname']]['status'] != 'matched'})
w('Non-matched nicknames among `review` Expense rows: %s.\n' % (', '.join(rev_nick) or 'none'))
# ---- routes
w('## 4. Rows paid through another payee\'s account or another entity\n')
w('| row | nickname | amount | route | load | comment |\n|---:|---|---:|---|---|---|')
for r in rows:
    if r.get('route'): w('| %d | %s | %s | %s | %s | %s |' % (r['rowNo'], r['nickname'], r['amount'], r['route'], r['load'], r['comment'][:90]))
w('\nNo Main comment mentions "tipalti" or "через ..."; the NoGhost 25,000 via an artist\'s Tipalti account is only on the separate sheet "выплаты саблейблам" (not in this ledger). "Send to fl" = third account "fl"; "выплатили с echo" = paid from the Echo8 contour (same payee); "Send to customer" is unexplained (listed here, loaded as a payout on the nickname).\n')
# ---- no recap
w('## 5. "ноу рекап" rows\n')
nr = [r for r in rows if r.get('noRecap')]
w('Found **%d** rows (Income %d, Expense %d); plan 4.5 says 15, the sheet has %d: %d of them are zero-amount Income rows. Expense rows are loaded as plain payouts with the note; Income rows stay for the comparison.\n' % (len(nr), sum(1 for r in nr if r['side'] == 'income'), sum(1 for r in nr if r['side'] == 'expense'), len(nr), sum(1 for r in nr if D(r['amountRaw']) == 0)))
w('| row | side | nickname | date | amount | comment |\n|---:|---|---|---|---:|---|')
for r in nr: w('| %d | %s | %s | %s | %s | %s |' % (r['rowNo'], r['side'], r['nickname'], r['date'], r['amount'], r['comment']))
# ---- overpayments
w('\n## 6. Overpayment rows\n')
w('| row | nickname | amount | load | treatment |\n|---:|---|---:|---|---|')
for r in rows:
    if r.get('overpayment'): w('| %d | %s | %s | %s | %s |' % (r['rowNo'], r['nickname'], r['amount'], r['load'], r['why']))
w('\nNot rows but ledger balances noted in the cases file (M27): Lost Label LLC income 82,382.31 vs expense 86,487.24 (overpaid 4,104.93); the Sleeping City Funk overpayment is the MC Denny row 12904.\n')
# ---- advances
w('## 7. Advances (Expense/Advance + the 9,500 overpayment)\n')
adv = [r for r in rows if r['load'] == 'advance']
c = collections.Counter(r['scope'] for r in adv)
w('Advance rows: %d (%s); sum %s. Scope from Sch3B v7 on nickname + date + amount: %d matched; %d default `any` (older or fully recouped advances are not in Sch3B, which lists only open/partial ones since 2024-09). Plain payouts by Sch3B scope `none`: 2 rows (10,500). Zero-amount advance rows: 2 (not loaded).\n' % (len(adv), ', '.join('%s %d' % kv for kv in sorted(c.items())), f(sum(D(r['amountRaw']) for r in adv)), sum(1 for r in adv if r['scopeSource'].startswith('Sch3B')), sum(1 for r in adv if r['scopeSource'].startswith('default'))))
un = [s for s in sch if not s['used']]
w('Sch3B rows without a Main Expense/Advance row: %d.\n' % len(un))
for s in un: w('- %s %s %s (scope %s, %s): no ledger advance row for that recipient/date/amount; the NoGhost sublabel payment of 25,000 was routed through an artist\'s account (sheet "выплаты саблейблам"), so it is not a Main nickname row.' % (s['nick'], s['date'], s['amount'], s['scope'], s['status']))
w('')
# ---- sample
w('## 8. Expense/Sample, row by row\n')
samp = [r for r in exp_rows if r['category'] == 'Sample']
w('Total %d rows, %s. Carve ("вычет доли") rows: %d rows %s (plus 1 carve-like row 10387, 49.43, worded "taken from royalty and passed on"). The other rows:\n' % (len(samp), f(sum(D(r['amountRaw']) for r in samp)), sum(1 for r in samp if r['load'] == 'carve_pair'), f(sum(D(r['amountRaw']) for r in samp if r['load'] == 'carve_pair'))))
w('| row | nickname | date | amount | load | why |\n|---:|---|---|---:|---|---|')
for r in samp:
    if r['load'] != 'carve_pair': w('| %d | %s | %s | %s | %s | %s |' % (r['rowNo'], r['nickname'], r['date'], r['amount'], r['load'], r['why'][:230]))
w('\nThe 100,000 row (11936): checked against the settlement lump and the buy-out prices of `agent_special_cases.md` and classified `review` (nickname does not match the settlement counterparty, nor any 100,000 buy-out price; see the row).\n')
# ---- other
w('## 9. Expense/Other (buy-out prices and one-off fees)\n')
oth = [r for r in exp_rows if r['category'] == 'Other' and r['load'] != 'not_loaded']
w('| row | nickname | date | amount | load | price check / why |\n|---:|---|---|---:|---|---|')
for r in oth:
    ev = r.get('evidence', {}); e = ''
    if ev.get('priceInDocs'): e = 'docs price %s: %s; ' % (ev['priceInDocs'], 'matches' if ev['priceMatchesRow'] else 'row is an installment / differs')
    elif ev: e = 'purchase document for the nickname: %s; ' % ('yes' if ev.get('purchaseDocForNickname') else 'not found by name') + ''
    w('| %d | %s | %s | %s | %s | %s%s |' % (r['rowNo'], r['nickname'], r['date'], r['amount'], r['load'], e, r['why'][:150]))
w('\nInstallments of the same buy-out (price = sum): DJ Ikeraus 24,500.32 + 25,499.68 = 50,000 (agreement 2025-12-16); Lxzt 10,000 + 10,000 + 10,000 + 20,000 = 50,000 (the Lxzt $50,000 agreement); DJ ZENITE 4 x 9,500 + 2,000 = 40,000 (listed price $40,000). Prices are in `agent_special_cases.md`; row amounts are not in a structured table, so `priceInDocs` is filled only where that file names the nickname and price.\n')
# ---- carve pairs
w('## 10. Carve pairs (Expense/Sample "вычет доли" and the matching credits)\n')
w('%d groups (participant + UPC set + report month); `deducted` = sum of the artists\' deduction rows (carve-like row included). Rows on the participant side (Income/Sample and Income/Other credits): see the second table.\n' % len(pairs))
w('| participant | UPC / title | month | % | artist rows | deducted |\n|---|---|---|---|---:|---:|')
for g in pairs:
    w('| %s | %s | %s | %s | %d | %s |' % (', '.join(g['participants']) or '?', ', '.join(sorted(set(g['upcs']))) or (g['title'] or '?'), g['reportMonth'], '/'.join(g['percents']), len(g['rows']), g['total']))
w('\nTotal deducted over groups: %s.\n' % f(sum(D(g['total']) for g in pairs)))
w('| row | nickname | date | amount | credit side of |\n|---:|---|---|---:|---|')
for r in rows:
    if r['load'] == 'carve_pair' and r.get('role') == 'participant_credit':
        w('| %d | %s | %s | %s | %s |' % (r['rowNo'], r['nickname'], r['date'], r['amount'], r['comment'][:100] or ('paid out by Expense/Other row %s' % r.get('pairedRow'))))
w('\nWhether a pair is covered by a carve in step 4.3 is decided there; for uncovered pairs the plan loads the artist rows as deductions with a note (`load` stays `carve_pair`, so the loader can switch per pair).\n')
# ---- review
w('## 11. Left in `review`\n')
rv = [r for r in rows if r['load'] == 'review']
w('%d rows, %s. | row | side | category | nickname | date | amount | why |\n' % (len(rv), f(sum(D(r['amountRaw']) for r in rv))))
w('|---:|---|---|---|---|---:|---|')
for r in rv: w('| %d | %s | %s | %s | %s | %s | %s |' % (r['rowNo'], r['side'], r['category'], r['nickname'], r['date'], r['amount'], r['why'][:260]))
open(os.path.join(OUT, 'reconciliation.md'), 'w').write('\n'.join(L) + '\n')

# ---- README
cnt = collections.Counter((r['side'], r['load']) for r in rows)
R = []
R.append('# data/mvp-load/main (stage 4.5 input)\n')
R.append('Git-ignored. Built read-only from `context_data/0to8 Main.xlsx` (sheet "INCOME  EXPENSE"), `реестры_каталога_2026-08_v7.xlsx` (Sch3B Авансы) and the ERP PostgreSQL (SELECT on `owners.artists`, `owners.owner_aliases`). Rebuild: `python3 -I packages/backend/scripts/mvp/build_main.py && python3 -I packages/backend/scripts/mvp/report_main.py`.\n')
R.append('| file | content |\n|---|---|\n| `nicknames.json` | every distinct nickname of the sheet -> status, artistId, ownerId, pseudonym, row/sum stats |\n| `cash_rows.json` | every row with a Type (%d), with classification `load`, `why` and extras |\n| `carve_pairs.json` | the carve ("вычет доли") rows grouped by participant + UPC + month |\n| `sch3b_check.json` | Sch3B v7 rows with a flag whether a ledger advance row was matched |\n| `reconciliation.md` | sums per class, the 8,045,246.75 proof, lists |\n' % len(rows))
R.append('## Nicknames\n\nExact match of lower-cased, trimmed, space-collapsed nickname against the lower-cased pseudonym (the ERP `pseudonym_norm` also strips punctuation; matching on it adds no new nickname), else against owner aliases. Never guessed: several artists -> `ambiguous`; none -> `unmatched`.\n')
R.append('- distinct nicknames: %d; matched %d; ambiguous %d; unmatched %d\n' % (len(nicks), st['matched'], st['ambiguous'], st['unmatched']))
R.append('- ambiguous: %s\n' % ', '.join(n for n, e in nicks.items() if e['status'] == 'ambiguous'))
R.append('- nicknames with loaded cash that are not matched: %d (see reconciliation.md section 3)\n' % len(bad))
R.append('## cash_rows.json fields\n\n`rowNo` (sheet row), `comment`, `reportMonth` (YYYY-MM or null), `date` (col C), `nickname`, `type`, `category`, `amount` (2 decimals, half-up), `amountRaw` (exact cell), `ignoreFlag`, `side` (`expense`|`income`), `load`, `why`, plus optional `scope`/`scopeSource`/`sch3bStatus` (advances), `route`, `noRecap`, `overpayment`, `parts` (rows with two meanings), `carve` (parsed title, UPCs, percents, participants), `role` (`artist_deduction`|`participant_credit`), `pairedRow`/`requiresCredit`, `evidence` (buy-out price check), `basis`, `nicknameStatus`, `ownerId`, `artistId`.\n')
R.append('Classes (`load`): Expense: payout, advance, deduction, carve_pair, document_only, not_loaded, review. Income rows: `income_comparison` (stage 5 only), `carve_pair` (participant credits), `review`.\n')
R.append('Row counts (a row with `parts` is counted under its primary class `payout`/`carve_pair`):\n')
R.append('| side | load | rows |\n|---|---|---:|')
for k in sorted(cnt): R.append('| %s | %s | %d |' % (k[0], k[1], cnt[k]))
R.append('\n## Decisions made while classifying (for the owner / stage 4.5 author)\n')
R.append('1. IGNORE Reports=1 does not make an Expense row `not_loaded`: it is a report-balance flag, the cash was paid (publishing-scope advances, buy-out prices, bonuses carry it). `not_loaded` = Advertising (7 rows, 2,699.39) and 55 zero/empty-amount Expense cells. The one Expense/Royalties row with the flag is `review`.\n2. Two rows have parts: row 12904 (MC Denny 15,774.41 = 10,774.41 payout + 5,000 fee document) and row 6821 (DJ Raulipues 41,905.62 = 19,660.71 carve + 22,244.91 deduction of a payment to a representative and a lawyer).\n3. Expense/Other rows of MC 7belo and MC JHonny (19,660.71; 4,010.83) and Expense/Sample of the third held payout (owner 7129f35a) 2,092.57 are cash paid to a participant the same day his credit (Income/Other, Income/Sample, equal amount) appeared: `payout` with `requiresCredit`; load only together with the carve, else payable goes negative.\n4. Expense/Sample rows without a comment: round sums -> `payout` (stage-2 product review: cash to artists), non-round sums and two equal-amount pairs -> `review`.\n5. Sample "вычет доли": 104 rows (219,095.20) + carve-like row 10387 (49.43) = 105 `carve_pair` rows (219,144.63).\n6. "ноу рекап": 17 rows found (13 Income, 4 Expense), not 15.\n')
open(os.path.join(OUT, 'README.md'), 'w').write('\n'.join(R) + '\n')
print('ok', f(exp_total), f(exp_cents))
